import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {properties} from '../data/properties.js';
import {projects} from '../data/projects.js';
import {developers} from '../data/developers.js';
import {locations} from '../data/locations.js';
import {filterListings,filterLocations} from '../lib/discovery.js';
import {validateLead,submitLead} from '../lib/leads.js';
test('demo inventory has valid relationships and local images',()=>{assert.equal(properties.length,18);assert.equal(projects.length,0);for(const items of [properties]){assert.equal(new Set(items.map(x=>x.slug)).size,items.length);for(const p of items){assert(p.demo);assert(developers.some(x=>x.slug===p.developerSlug));assert(locations.some(x=>x.slug===p.locationSlug));for(const image of p.gallery)assert(fs.existsSync(`public${image}`));if(p.paymentPlan.length)assert.equal(p.paymentPlan.reduce((n,x)=>n+x.percent,0),100);}}});
test('combined filters, zero bedrooms, empty results and sorting',()=>{assert.equal(filterListings(properties,{location:'Dubai Creek Harbour'}).length,2);assert.equal(filterListings(properties,{bedrooms:'0'}).length,2);assert.equal(filterListings(properties,{purpose:'Rent',status:'Off-Plan'}).length,0);assert.equal(filterListings(properties,{developer:'Emaar',propertyType:'Apartment'}).length,2);const sorted=filterListings(properties,{},'price-asc');assert(sorted.every((x,i)=>!i||x.price>=sorted[i-1].price));assert(filterListings(projects,{},'featured','Waterfront').every(x=>x.tags.includes('Waterfront')));});
test('projects filter by property type matches against tags, not propertyType field',()=>{const sampleProjects=[{id:'1',title:'Project Alpha',propertyType:'Community Living',tags:['Modern Residential Apartments in Dubai','Green Community']},{id:'2',title:'Project Beta',propertyType:'Apartment',tags:['Luxury Villas & Townhouses']},{id:'3',title:'Project Gamma',propertyType:'Mixed Use',tags:['Sobha Sanctuary Villas']},{id:'4',title:'Project Delta',propertyType:'Commercial',tags:['Commercial Space','Offices']}];const apts=filterListings(sampleProjects,{propertyType:'Apartment'},'featured','All','projects');assert.equal(apts.length,1);assert.equal(apts[0].id,'1');const villas=filterListings(sampleProjects,{propertyType:'Villa'},'featured','All','projects');assert.equal(villas.length,2);const townhouses=filterListings(sampleProjects,{propertyType:'Townhouse'},'featured','All','projects');assert.equal(townhouses.length,1);assert.equal(townhouses[0].id,'2');const commercial=filterListings(sampleProjects,{propertyType:'Commercial'},'featured','All','projects');assert.equal(commercial.length,1);assert.equal(commercial[0].id,'4');});
test('enquiries reject invalid input and never claim delivery',async()=>{assert(validateLead({}).email);assert(validateLead({name:'Test',email:'bad',phone:'123',consent:true}).phone);assert(validateLead({name:'Test',email:'test@example.com',phone:'+971 500000000',consent:true,variant:'referral'}).country);assert.deepEqual(validateLead({name:'Demo Visitor',email:'test@example.com',phone:'+971 500000000',country:'UAE',nationality:'Emirati',consent:true,variant:'referral'}),{});assert.deepEqual(validateLead({name:'Demo Visitor',email:'test@example.com',phone:'+971 500000000',consent:true}),{});assert.deepEqual(await submitLead(),{mode:'demo',delivered:false,stored:false});});
test('locations filter hides locations flagged as hideInPopularLocations from Popular category',()=>{const sampleLocations=[{id:'1',name:'Downtown Dubai',category:'Popular',hideInPopularLocations:false},{id:'2',name:'Dubai Marina',category:'Popular',hideInPopularLocations:true},{id:'3',name:'Business Bay',category:'Popular',hideInPopular:true},{id:'4',name:'Dubai Hills Estate',category:'Popular'},{id:'5',name:'JVC',category:'Emerging',hideInPopularLocations:false}];const popular=filterLocations(sampleLocations,{category:'Popular'});assert.equal(popular.length,2);assert.deepEqual(popular.map(x=>x.name),['Downtown Dubai','Dubai Hills Estate']);const all=filterLocations(sampleLocations,{category:'All'});assert.equal(all.length,5);const searchDowntown=filterLocations(sampleLocations,{query:'Downtown',category:'Popular'});assert.equal(searchDowntown.length,1);assert.equal(searchDowntown[0].name,'Downtown Dubai');const searchMarina=filterLocations(sampleLocations,{query:'Marina',category:'Popular'});assert.equal(searchMarina.length,0);});
